/**
 * All ways a bundle open/read can fail over the FFI surface.
 */
public 
enum FfiError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * The bundle's `schemaVersion` is not one this reader supports —
     * surface "upgrade your app" copy.
     */
    case UnknownSchema(
        /**
         * Version found in the bundle manifest.
         */found: UInt32, 
        /**
         * Highest version this reader understands.
         */supported: UInt32
    )
    /**
     * A required entry (`manifest.json`, `text.json`) is missing.
     */
    case MissingEntry(
        /**
         * The absent entry's name.
         */entry: String
    )
    /**
     * The archive itself is corrupt or unreadable.
     */
    case CorruptArchive(
        /**
         * The underlying zip failure, stringified.
         */detail: String
    )
    /**
     * A JSON entry failed to parse.
     */
    case CorruptJson(
        /**
         * The underlying parse failure, stringified.
         */detail: String
    )
    /**
     * An I/O error reading the bytes.
     */
    case Io(
        /**
         * The underlying I/O failure, stringified.
         */detail: String
    )
    /**
     * An archive entry's decompressed size exceeded the per-entry cap.
     */
    case EntryTooLarge(
        /**
         * The offending entry's archive name.
         */name: String, 
        /**
         * The per-entry cap that was exceeded.
         */limit: UInt64
    )
    /**
     * An audio content key is not a safe single name component —
     * rejected before any archive lookup.
     */
    case InvalidAudioKey(
        /**
         * The rejected key.
         */key: String
    )
    /**
     * The summed decompressed size of an archive's entries exceeded the
     * total budget.
     */
    case TotalTooLarge(
        /**
         * The archive-level budget that was exceeded.
         */limit: UInt64
    )
    /**
     * An audio segment's bytes could not be decoded to PCM (not
     * OGG/Opus or 16-bit PCM WAV, or corrupt within its codec) — the
     * platform maps this onto the kernel's segment-skip path.
     */
    case DecodeFailed(
        /**
         * The underlying decode failure, one sentence.
         */detail: String
    )
    /**
     * A whole-book audio merge (export) failed: the bundle is text-only,
     * its codec is not Opus, or a segment's OGG payload is malformed —
     * the host surfaces this as "export failed" copy, never a crash.
     */
    case MergeFailed(
        /**
         * The underlying merge failure, one sentence.
         */detail: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension FfiError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiError: FfiConverterRustBuffer {
    typealias SwiftType = FfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .UnknownSchema(
            found: try FfiConverterUInt32.read(from: &buf), 
            supported: try FfiConverterUInt32.read(from: &buf)
            )
        case 2: return .MissingEntry(
            entry: try FfiConverterString.read(from: &buf)
            )
        case 3: return .CorruptArchive(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 4: return .CorruptJson(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Io(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 6: return .EntryTooLarge(
            name: try FfiConverterString.read(from: &buf), 
            limit: try FfiConverterUInt64.read(from: &buf)
            )
        case 7: return .InvalidAudioKey(
            key: try FfiConverterString.read(from: &buf)
            )
        case 8: return .TotalTooLarge(
            limit: try FfiConverterUInt64.read(from: &buf)
            )
        case 9: return .DecodeFailed(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 10: return .MergeFailed(
            detail: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .UnknownSchema(found,supported):
            writeInt(&buf, Int32(1))
            FfiConverterUInt32.write(found, into: &buf)
            FfiConverterUInt32.write(supported, into: &buf)
            
        
        case let .MissingEntry(entry):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(entry, into: &buf)
            
        
        case let .CorruptArchive(detail):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .CorruptJson(detail):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Io(detail):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .EntryTooLarge(name,limit):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(name, into: &buf)
            FfiConverterUInt64.write(limit, into: &buf)
            
        
        case let .InvalidAudioKey(key):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(key, into: &buf)
            
        
        case let .TotalTooLarge(limit):
            writeInt(&buf, Int32(8))
            FfiConverterUInt64.write(limit, into: &buf)
            
        
        case let .DecodeFailed(detail):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .MergeFailed(detail):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(detail, into: &buf)
            
        }
    }
}


