/**
 * Progress observer for voice/espeak downloads. **Threading:** events
 * arrive on the calling thread (these calls are synchronous) — but see
 * [`crate::PipelineObserver`] for the async pipeline's contract.
 */
public protocol FfiVoiceObserver: AnyObject, Sendable {
    
    /**
     * Download progress: `bytes_done` of `bytes_total` (`0` = unknown).
     */
    func onDownloadStep(bytesDone: UInt64, bytesTotal: UInt64) 
    
}


// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceFfiVoiceObserver {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceFfiVoiceObserver = UniffiVTableCallbackInterfaceFfiVoiceObserver(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterCallbackInterfaceFfiVoiceObserver.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface FfiVoiceObserver: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterCallbackInterfaceFfiVoiceObserver.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface FfiVoiceObserver: handle missing in uniffiClone")
            }
        },
        onDownloadStep: { (
            uniffiHandle: UInt64,
            bytesDone: UInt64,
            bytesTotal: UInt64,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterCallbackInterfaceFfiVoiceObserver.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.onDownloadStep(
                     bytesDone: try FfiConverterUInt64.lift(bytesDone),
                     bytesTotal: try FfiConverterUInt64.lift(bytesTotal)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
